import random

def check_all_signs(c_list):
    n = len(c_list)
    # For larger n, we can't use itertools.product.
    # We can use a simple randomized search or a greedy approach.
    # Let's use a randomized search to see if there is a way to avoid.
    # If we can't find a way to avoid after 1000 tries, we say "maybe it's covered".

    def is_circle_covered(signs):
        x = 0.0
        intervals = []
        for i in range(n):
            c = c_list[i]
            s = signs[i]
            x_next = (x + s * c) % 1
            if s == 1:
                if x + c <= 1:
                    intervals.append((x, x + c))
                else:
                    intervals.append((x, 1.0))
                    intervals.append((0.0, (x + c) % 1))
            else:
                if x - c >= 0:
                    intervals.append((x - c, x))
                else:
                    intervals.append(((x - c) % 1, 1.0))
                    intervals.append((0.0, x))
            x = x_next

        intervals.sort()
        curr_max = 0.0
        for start, end in intervals:
            if start > curr_max + 1e-9: return False
            curr_max = max(curr_max, end)
        return curr_max >= 1.0 - 1e-9

    # Try 1000 random sign sequences.
    for _ in range(1000):
        signs = [random.choice([1, -1]) for _ in range(n)]
        if not is_circle_covered(signs):
            return False # Found a way to avoid
    return True

def find_forcing_sequence(C, n=10):
    for _ in range(1000):
        c_list = [random.uniform(0, C) for _ in range(n)]
        if check_all_signs(c_list):
            return c_list
    return None

